import{_t as e,it as t,n,rt as r}from"./chunks/framework.CdvHacad.js";var i=JSON.parse(`{"title":"Standards Scope","description":"","frontmatter":{"outline":[2,3],"packageVersion":"0.16.0"},"headers":[],"relativePath":"reference/standards.md","filePath":"site/reference/standards.md","lastUpdated":1792852428000}`),a={name:`reference/standards.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="standards-scope" tabindex="-1">Standards Scope <a class="header-anchor" href="#standards-scope" aria-label="Permalink to “Standards Scope”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td><a href="https://www.rfc-editor.org/rfc/rfc5280.html" target="_blank" rel="noreferrer">RFC 5280</a> path validation</td><td>complete</td><td>Full NIST PKITS suite passes (224 procedures, 249 runs; DSA chains expected-fail per the WebCrypto algorithm boundary); revocation is a separate API by design</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc6960.html" target="_blank" rel="noreferrer">RFC 6960</a> + <a href="https://www.rfc-editor.org/rfc/rfc9919.html" target="_blank" rel="noreferrer">9919</a> OCSP</td><td>complete</td><td>Full validation surface: parsing, signatures, responder authorization, revocation policy, nonce, freshness, chain orchestration; CertID hashing defaults to SHA-256 per <a href="https://www.rfc-editor.org/rfc/rfc9919.html#section-3.1.1" target="_blank" rel="noreferrer">RFC 9919 §3.1.1</a> with explicit SHA-1 interop; opt-in <a href="https://www.rfc-editor.org/rfc/rfc9919.html" target="_blank" rel="noreferrer">RFC 9919</a> client profile rejects a response without <code>nextUpdate</code>, and the <a href="https://www.rfc-editor.org/rfc/rfc6960.html" target="_blank" rel="noreferrer">RFC 6960</a> default accepts it; HTTP transport caller-provided by design</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9525.html" target="_blank" rel="noreferrer">RFC 9525</a> service identity</td><td>complete</td><td>Every identity type: DNS-ID, IP-ID, URI-ID, SRV-ID, wildcard, IDNA, opt-in <a href="https://www.rfc-editor.org/rfc/rfc6125.html" target="_blank" rel="noreferrer">RFC 6125</a> CN-compat</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc9618.html" target="_blank" rel="noreferrer">RFC 9618</a> policy validation</td><td>complete</td><td>Full PKITS policy sections (4.8–4.12, every documented subtest variation) pass</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc7468.html" target="_blank" rel="noreferrer">RFC 7468</a> PEM textual encodings</td><td>complete</td><td>Strict generator/parser conformance backed by a section-complete executable suite; non-canonical base64 final quanta rejected per <a href="https://www.rfc-editor.org/rfc/rfc4648.html#section-3.5" target="_blank" rel="noreferrer">RFC 4648 §3.5</a>; <a href="https://www.rfc-editor.org/rfc/rfc1421.html" target="_blank" rel="noreferrer">RFC 1421</a> folded encapsulated headers unfold for legacy traditional PEM</td></tr><tr><td><a href="https://www.rfc-editor.org/rfc/rfc8410.html" target="_blank" rel="noreferrer">RFC 8410</a> + <a href="https://www.rfc-editor.org/rfc/rfc9295.html" target="_blank" rel="noreferrer">9295</a> safe-curve profiles</td><td>complete</td><td>Ed25519 end-to-end (keys, CSRs, certificates, signatures); Ed448/X25519/X448 parse with <a href="https://www.rfc-editor.org/rfc/rfc9295.html#section-3" target="_blank" rel="noreferrer">RFC 9295 §3</a> key-usage enforcement, their key operations outside the WebCrypto boundary; section-complete executable suite</td></tr><tr><td>PKCS containers: <a href="https://www.rfc-editor.org/rfc/rfc5652.html" target="_blank" rel="noreferrer">RFC 5652</a>, <a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">7292</a>, <a href="https://www.rfc-editor.org/rfc/rfc8018.html" target="_blank" rel="noreferrer">8018</a>, <a href="https://www.rfc-editor.org/rfc/rfc9879.html" target="_blank" rel="noreferrer">9879</a></td><td>partial</td><td>SignedData sign/parse/verify with signer resolution and cert bags (<a href="https://www.rfc-editor.org/rfc/rfc5652.html" target="_blank" rel="noreferrer">RFC 5652</a> subset); PFX create/parse with BER input and a SHA-256-only MAC (<a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> subset); <a href="https://www.rfc-editor.org/rfc/rfc9879.html" target="_blank" rel="noreferrer">RFC 9879</a> PBMAC1 verification and opt-in creation; PBES2 with PBKDF2 HMAC-SHA-1/256 and AES-CBC (<a href="https://www.rfc-editor.org/rfc/rfc8018.html" target="_blank" rel="noreferrer">RFC 8018</a> subset); no enveloped/encrypted CMS content types</td></tr></tbody></table><h2 id="what-ships" tabindex="-1">What ships <a class="header-anchor" href="#what-ships" aria-label="Permalink to “What ships”">​</a></h2><h3 id="rfc-5280-path-validation" tabindex="-1">RFC 5280 path validation <a class="header-anchor" href="#rfc-5280-path-validation" aria-label="Permalink to “RFC 5280 path validation”">​</a></h3><ul><li>DER encoding on output; parsing rejects malformed certificates and tolerates an explicitly encoded DEFAULT value (certificate version v1, <code>critical</code> FALSE, <code>cA</code> FALSE) as local policy per X.509 §7.2.1 NOTE 2</li><li>BOOLEAN content other than a single <code>0x00</code> or <code>0xFF</code> octet rejected</li><li>Issuer/subject chaining across candidate paths</li><li>Signature verification using the evolving working public key</li><li>Validity time checks (<code>notBefore</code> / <code>notAfter</code>)</li><li><code>basicConstraints</code> enforcement for CA certificates</li><li><code>pathLenConstraint</code> enforcement</li><li><code>keyUsage</code> enforcement (<code>keyCertSign</code> for CAs)</li><li>Self-issued vs non-self-issued processing</li><li>Name constraints: enforced for DNS, URI, email, IP, and directoryName; rfc822Name constraints also bind SmtpUTF8Mailbox SANs by domain (<a href="https://www.rfc-editor.org/rfc/rfc9598.html#section-6" target="_blank" rel="noreferrer">RFC 9598 §6</a>); fail-closed for otherName / x400Address / ediPartyName / registeredID when a critical constraint meets a SAN of that form (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-4.2.1.10" target="_blank" rel="noreferrer">RFC 5280 §4.2.1.10</a>)</li><li>Critical extension rejection for unrecognized OIDs</li><li><code>noRevAvail</code> (<a href="https://www.rfc-editor.org/rfc/rfc9608.html" target="_blank" rel="noreferrer">RFC 9608</a>): parsed, emitted by the builder, and a certificate pairing it with cA TRUE, cRLDistributionPoints, freshestCRL or an <code>id-ad-ocsp</code> location is rejected</li></ul><h3 id="rfc-6960-ocsp" tabindex="-1">RFC 6960 OCSP <a class="header-anchor" href="#rfc-6960-ocsp" aria-label="Permalink to “RFC 6960 OCSP”">​</a></h3><ul><li>Request creation with CertID (issuer hash + serial)</li><li>Response parsing with status, certs, timestamps</li><li>Signature verification</li><li>Responder authorization (CA-signed, delegated with <code>ocspSigning</code> EKU, locally trusted responders per <a href="https://www.rfc-editor.org/rfc/rfc6960.html#section-4.2.2.2" target="_blank" rel="noreferrer">RFC 6960 §4.2.2.2</a> criterion 1)</li><li>Delegated responder revocation policy: <code>id-pkix-ocsp-nocheck</code> (<code>hasOcspNoCheckExtension()</code>), <code>honor-nocheck</code> / <code>require-evidence</code> / <code>skip</code> knobs with CRL evidence</li><li>Historical-time responder chain validation (<code>at</code> flows through delegated chain checks)</li><li>Nonce matching</li><li>Freshness checks, with <code>clockSkewMs</code></li><li>Opt-in <a href="https://www.rfc-editor.org/rfc/rfc9919.html" target="_blank" rel="noreferrer">RFC 9919</a> client profile. <code>profile: &#39;rfc9919&#39;</code> on <code>validateOcspResponse</code> (<code>ocspProfile: &#39;rfc9919&#39;</code> on <code>checkCertificateRevocation</code> and the chain <code>RevocationPolicy</code>) rejects a response without <code>nextUpdate</code> (<a href="https://www.rfc-editor.org/rfc/rfc9919.html#section-5" target="_blank" rel="noreferrer">RFC 9919 §5</a>). The default <code>&#39;rfc6960&#39;</code> profile accepts it (<a href="https://www.rfc-editor.org/rfc/rfc6960.html#section-4.2.2.1" target="_blank" rel="noreferrer">RFC 6960 §4.2.2.1</a>)</li><li>Chain-level orchestration: <code>checkChainRevocation()</code> / <code>verifyCertificateChain({ revocation })</code> consume caller-supplied OCSP responses alongside CRLs</li><li>Chain-level revocation reports a certificate carrying <code>noRevAvail</code> or <code>id-pkix-ocsp-nocheck</code> as <code>skipped</code> without consulting evidence (<a href="https://www.rfc-editor.org/rfc/rfc9608.html#section-4" target="_blank" rel="noreferrer">RFC 9608 §4</a>)</li></ul><h3 id="crl-processing" tabindex="-1">CRL processing <a class="header-anchor" href="#crl-processing" aria-label="Permalink to “CRL processing”">​</a></h3><ul><li>Delta CRL merge using only a current delta whose CRL number exceeds its base&#39;s and preferring the latest <code>thisUpdate</code> (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-5.2.4" target="_blank" rel="noreferrer">RFC 5280 §5.2.4</a>), with a <code>thisUpdate</code> no earlier than the base&#39;s (X.509 Annex E.5.2)</li><li>Generated CRLs always carry <code>nextUpdate</code> (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-5.1.2.5" target="_blank" rel="noreferrer">RFC 5280 §5.1.2.5</a>)</li><li>Received CRLs without <code>nextUpdate</code> stay usable unless <code>maxAgeMs</code> / <code>crlMaxAgeMs</code> bounds the age of <code>thisUpdate</code> (<a href="https://www.rfc-editor.org/rfc/rfc5280.html#section-3.3" target="_blank" rel="noreferrer">RFC 5280 §3.3</a> local policy); unbounded by default</li><li>Indirect issuer handling</li><li>Scope matching</li><li>Basic CRL parsing and revocation checks</li></ul><div class="tip custom-block"><p class="custom-block-title">Hard-fail default</p><p>Chain-level revocation checking runs only when evidence is supplied, and then defaults to <code>mode: &#39;hard-fail&#39;</code> — indeterminate status denies. Set <code>mode: &#39;soft-fail&#39;</code> explicitly to allow indeterminate results. See the <a href="/v0.16.0/guide/revocation">revocation guide</a>.</p></div><h3 id="pkcs-12-rfc-7292-rfc-9879" tabindex="-1">PKCS#12 (RFC 7292, RFC 9879) <a class="header-anchor" href="#pkcs-12-rfc-7292-rfc-9879" aria-label="Permalink to “PKCS#12 (RFC 7292, RFC 9879)”">​</a></h3><ul><li>PFX create and parse, with BER accepted for the PFX, AuthenticatedSafe and SafeContents layers and DER required for certificate and key bags</li><li><a href="https://www.rfc-editor.org/rfc/rfc7292.html" target="_blank" rel="noreferrer">RFC 7292</a> MAC with SHA-256 only; the password must be a BMPString</li><li><a href="https://www.rfc-editor.org/rfc/rfc9879.html" target="_blank" rel="noreferrer">RFC 9879</a> PBMAC1 verification with PBKDF2 and HMAC-SHA-256/384/512, and opt-in creation with <code>mac: { type: &#39;pbmac1&#39; }</code></li><li>KDF iteration budgets through <code>maxKdfIterations</code>; PBKDF2 counts are capped at 4294967295, the WebCrypto maximum</li></ul><h3 id="rfc-9525-service-identity" tabindex="-1">RFC 9525 service identity <a class="header-anchor" href="#rfc-9525-service-identity" aria-label="Permalink to “RFC 9525 service identity”">​</a></h3><ul><li>DNS-ID with single-level wildcard matching</li><li>IP-ID with IPv6 normalization</li><li>URI-ID scheme + host matching, the host read by <a href="https://www.rfc-editor.org/rfc/rfc3986.html" target="_blank" rel="noreferrer">RFC 3986</a>; an IP host by its octets, a DNS host with single-level wildcard matching except for SIP</li><li>SRV-ID via otherName SAN, with single-level wildcard matching</li><li>IDNA2008 reference conversion (<a href="https://www.rfc-editor.org/rfc/rfc5891.html" target="_blank" rel="noreferrer">RFC 5891</a> lookup, <a href="https://www.rfc-editor.org/rfc/rfc5895.html" target="_blank" rel="noreferrer">RFC 5895</a> mapping)</li><li>Opt-in CN compatibility (disabled by default)</li></ul><h3 id="rfc-9618-policy-validation" tabindex="-1">RFC 9618 policy validation <a class="header-anchor" href="#rfc-9618-policy-validation" aria-label="Permalink to “RFC 9618 policy validation”">​</a></h3><ul><li>Policy state tracking across candidate paths</li><li>Explicit policy enforcement</li><li>Initial policy set validation</li></ul><h2 id="what-doesn-t-ship" tabindex="-1">What doesn&#39;t ship <a class="header-anchor" href="#what-doesn-t-ship" aria-label="Permalink to “What doesn&#39;t ship”">​</a></h2><ul><li>Full CRL distribution point processing</li><li>OCSP/CRL HTTP fetching (evidence is caller-provided by design)</li><li>Semantic matching for otherName / x400Address / ediPartyName / registeredID name constraints (they fail closed instead when a critical constraint meets a name of that form)</li></ul><p>For the authoritative scope boundary, see <a href="https://github.com/kjanat/micro509/blob/master/docs/PKIX-SCOPE.md" target="_blank" rel="noreferrer"><code>PKIX-SCOPE.md</code></a>.</p>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};